    .top-bar { flex-wrap: wrap; gap: 8px; padding: 10px; }
    .content-area { padding: 0 12px; }
    .msg { max-width: 95%; }
}

input.new_string:
@media (max-width: 768px) {
    .top-bar { flex-wrap: wrap; gap: 8px; padding: 10px; }
    .top-bar-left, .top-bar-right { flex-wrap: wrap; gap: 6px; min-width: 0; }
    .top-bar button, .top-bar select { font-size: 0.75rem; padding: 6px 10px; }
    .content-area { padding: 0 12px; }
    .msg { max-width: 95%; }
}
